const $=s=>document.querySelector(s);const cards=[{name:'小试手气',cost:100,max:100000,unlock:0,color:'#db4630'},{name:'黄金时代',cost:10000,max:10000000,unlock:8,color:'#a47528'},{name:'一夜星光',cost:1000000,max:1000000000,unlock:20,color:'#4c557c'}];
const defaults={coins:10000,count:0,earned:0,best:0,luck:0,levels:[0,0,0],selected:0,current:null,streak:0,boostVersion:2};let s;try{const old=JSON.parse(localStorage.getItem('scratch-club-v1')||'null');s={...defaults,...old};if(old&&!old.boostVersion)s.boostVersion=0}catch{s={...defaults}}if(!s.boostVersion){s.coins=Math.max(10000,s.coins*100);s.streak=0;s.boostVersion=2;if(s.current&&!s.current.done)s.current=null;}let active=false,last=null,ctx=$('#cover').getContext('2d'),timer;
function save(){try{localStorage.setItem('scratch-club-v1',JSON.stringify(s))}catch{toast('当前浏览器无法保存进度，请勿关闭页面')}}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
const costs=i=>Math.floor([1500,3000,5000][i]*2.6**s.levels[i]);
function render(){const c=cards[s.selected];$('#balance').textContent=fmt(s.coins);$('#count').textContent=s.count+' 张';$('#earned').textContent=fmt(s.earned)+' ◉';$('#best').textContent=fmt(s.best)+' ◉';$('#luckText').textContent=s.luck>=5?'幸运已满 · 下一张必中奖':s.luck+' / 5 · 未中奖积攒幸运';$('#luckBar').style.width=s.luck/5*100+'%';$('#types').innerHTML=cards.map((c,i)=>`<button class="type ${i===s.selected?'active':''}" data-card="${i}" ${s.count<c.unlock?'disabled':''}><b>${['✳','✦','✧'][i]} ${c.name}</b><small>${s.count<c.unlock?'刮满 '+c.unlock+' 张解锁':fmt(c.cost)+' 金币 / 张'}</small></button>`).join('');$('#upgrades').innerHTML=['顺手的刮刀','奖金放大镜','幸运四叶草'].map((name,i)=>`<button class="upgrade" data-up="${i}" ${s.coins<costs(i)||s.levels[i]>=10?'disabled':''}><span class="icon">${['▰','⌕','✤'][i]}</span><span class="info"><b>${name}</b><small>${['刮开范围 +20% / 级','所有奖金 ×2 / 级','中奖概率 +2% / 级'][i]}</small><em>${s.levels[i]>=10?'已满级':fmt(costs(i))+' ◉ · 升级 ↗'}</em></span><span class="level">LV.${s.levels[i]}</span></button>`).join('');$('#buy span').textContent=fmt(c.cost)+' ◉ →';$('#combo').textContent='连中 '+(s.streak||0)+' 张 · 奖金 ×'+Math.min(3,1+(s.streak||0)*.2).toFixed(1);$('#burstLeft').textContent=10-s.count%10;$('#burstBar').style.width=(s.count%10)*10+'%';$('#buy').disabled=!!s.current&&!s.current.done;$('#reveal').disabled=!s.current||s.current.done;}
function paint(){const canvas=$('#cover'),r=$('#area').getBoundingClientRect();canvas.width=Math.round(r.width-12);canvas.height=Math.round(r.height-12);canvas.style.display=s.current.done?'none':'block';ctx.globalCompositeOperation='source-over';const g=ctx.createLinearGradient(0,0,canvas.width,canvas.height);g.addColorStop(0,'#d4d7d2');g.addColorStop(.5,'#b5bcb8');g.addColorStop(1,'#d5d8d1');ctx.fillStyle=g;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#a3aaa5';for(let x=-200;x<canvas.width;x+=14){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x+200,canvas.height);ctx.strokeStyle='#ffffff30';ctx.stroke()}ctx.textAlign='center';ctx.fillStyle='#636f69';ctx.font='bold 20px sans-serif';ctx.fillText('✦ 刮 开 好 运 ✦',canvas.width/2,canvas.height/2-4);ctx.font='11px sans-serif';ctx.fillText('手指滑动此处，惊喜即刻揭晓',canvas.width/2,canvas.height/2+23);}
function display(){const t=s.current,c=cards[t.type];$('#ticket').style.background=c.color;$('#cardTitle').textContent=c.name;$('#ticketPrice').textContent=c.cost+' 金币 / 张';$('#maxPrize').textContent=fmt(Math.floor(c.max*(2**s.levels[1])*3));$('#serial').textContent=String(s.count+(t.done?0:1)).padStart(4,'0');$('#symbols').innerHTML=t.symbols.map(v=>`<div>${v}<small>${t.prize?'好运降临':'好运在路上'}</small></div>`).join('');$('#result').classList.toggle('win',t.done&&t.prize>0);$('#result').textContent=t.done?(t.prize?(t.jackpot?'十连爆奖！':t.prize>=cards[t.type].cost*50?'超级大奖！':'中奖啦！')+' +'+fmt(t.prize)+' 金币 · 连中 '+(s.streak||1)+' 张':'差一点点！幸运 +1，再试试手气。'):'按住并滑动，刮开银色涂层。';paint();render()}
function newCard(free=false){if(s.current&&!s.current.done)return;const c=cards[s.selected];if(!free&&s.coins<c.cost){toast('补给到账 +'+fmt(c.cost*3)+' 金币，继续开刮！');s.coins+=c.cost*3;save();render();return}if(!free)s.coins-=c.cost;const jackpot=(s.count+1)%10===0;const win=jackpot||s.luck>=5||Math.random()<Math.min(.98,.82+s.levels[2]*.02);const roll=Math.random();const base=jackpot?c.max:roll<.4?c.cost*5:roll<.75?c.cost*15:roll<.93?c.cost*50:c.max;const combo=win?Math.min(3,1+((s.streak||0)+1)*.2):1;const symbols=['🍒','🍋','🔔','⭐','🍀','💎'];const a=Math.floor(Math.random()*symbols.length);s.current={type:s.selected,jackpot,combo,prize:win?Math.floor(base*(2**s.levels[1])*combo):0,symbols:win?Array(3).fill(symbols[a]):[symbols[a],symbols[(a+1)%6],symbols[(a+3)%6]],done:false};save();display()}
function finish(){if(!s.current||s.current.done)return;const t=s.current;t.done=true;s.count++;s.streak=t.prize?(s.streak||0)+1:0;s.coins+=t.prize;s.earned+=t.prize;s.best=Math.max(s.best,t.prize);s.luck=t.prize?0:Math.min(5,s.luck+1);save();display();if(t.prize){celebrate(t);$('#ticket').classList.remove('celebrate');void $('#ticket').offsetWidth;$('#ticket').classList.add('celebrate')}}
$('#types').onclick=e=>{const b=e.target.closest('[data-card]');if(!b)return;const i=+b.dataset.card;if(s.current&&!s.current.done){toast('先刮完手里的这张吧');return}s.selected=i;save();render()};$('#upgrades').onclick=e=>{const b=e.target.closest('[data-up]');if(!b)return;const i=+b.dataset.up;if(s.levels[i]>=10||s.coins<costs(i))return;s.coins-=costs(i);s.levels[i]++;save();render();toast('升级成功，好运加码！')};$('#reveal').onclick=finish;$('#buy').onclick=()=>newCard();
const canvas=$('#cover');function scratch(e){const r=canvas.getBoundingClientRect(),p={x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};ctx.globalCompositeOperation='destination-out';ctx.lineWidth=36*(1+s.levels[0]*.2);ctx.lineCap='round';ctx.beginPath();ctx.moveTo(last?last.x:p.x,last?last.y:p.y);ctx.lineTo(p.x+.01,p.y+.01);ctx.stroke();last=p;const data=ctx.getImageData(0,0,canvas.width,canvas.height).data;let clear=0,total=0;for(let i=3;i<data.length;i+=64){total++;if(data[i]<100)clear++}if(clear/total>.6){active=false;finish()}}
canvas.onpointerdown=e=>{if(s.current.done)return;active=true;last=null;canvas.setPointerCapture(e.pointerId);scratch(e)};canvas.onpointermove=e=>{if(active)scratch(e)};canvas.onpointerup=canvas.onpointercancel=()=>{active=false;last=null};window.addEventListener('resize',()=>{if(s.current)paint()});if(s.current)display();else newCard(true);

function fmt(n){if(n>=1e12)return (n/1e12).toFixed(2)+'万亿';if(n>=1e8)return (n/1e8).toFixed(2)+'亿';if(n>=1e4)return (n/1e4).toFixed(2)+'万';return Math.floor(n).toLocaleString()}
function celebrate(t){const big=t.prize>=cards[t.type].cost*50;const el=document.createElement('div');el.className='payout '+(big?'mega':'');el.innerHTML='<small>'+(t.jackpot?'JACKPOT · 十连爆奖':big?'MEGA WIN · 超级大奖':'WIN · 好运连连')+'</small><strong>+'+fmt(t.prize)+'</strong><span>金币到账 · 奖金 ×'+(t.combo||1).toFixed(1)+'</span>';document.body.appendChild(el);setTimeout(()=>el.remove(),big?2400:1500);for(let i=0;i<(big?45:16);i++){const coin=document.createElement('i');coin.className='coin-rain';coin.textContent=['◉','✦','✧'][i%3];coin.style.left=Math.random()*100+'vw';coin.style.animationDelay=Math.random()*.5+'s';coin.style.setProperty('--drift',(Math.random()-.5)*300+'px');document.body.appendChild(coin);setTimeout(()=>coin.remove(),2800)}}
